import type { ExpansionSpec } from './types';
const refs = {
 pediatric: ['WHO Pocket Book of Hospital Care for Children, 2nd edition (2013)', 'https://www.who.int/publications/i/item/978-92-4-154837-3'],
 antibiotic: ['CDC: Pediatric outpatient clinical care', 'https://www.cdc.gov/antibiotic-use/hcp/clinical-care/pediatric-outpatient.html'],
 heart: ['NHLBI: Congenital heart defects, types', 'https://www.nhlbi.nih.gov/health/congenital-heart-defects/types'],
 pregnancy: ['ACOG: Bleeding during pregnancy', 'https://www.acog.org/womens-health/faqs/bleeding-during-pregnancy'],
 hypertension: ['ACOG: Preeclampsia and high blood pressure during pregnancy', 'https://www.acog.org/womens-health/faqs/preeclampsia-and-high-blood-pressure-during-pregnancy'],
 loss: ['ACOG: Early pregnancy loss', 'https://www.acog.org/womens-health/faqs/early-pregnancy-loss'],
 bleeding: ['ACOG: Abnormal uterine bleeding', 'https://www.acog.org/womens-health/faqs/abnormal-uterine-bleeding'],
 ectopic: ['ACOG: Ectopic pregnancy', 'https://www.acog.org/womens-health/faqs/ectopic-pregnancy'],
 clinical: ['Clinical Methods, 3rd edition: examination and diagnostic reasoning (1990)', 'https://www.ncbi.nlm.nih.gov/books/NBK201/'],
 appendicitis: ['NIDDK: Appendicitis', 'https://www.niddk.nih.gov/health-information/digestive-diseases/appendicitis'],
 intussusception: ['NIDDK: Intussusception', 'https://www.niddk.nih.gov/health-information/digestive-diseases/anatomic-problems-lower-gi-tract/intussusception'],
} satisfies Record<string, [string,string]>;
type Ref = keyof typeof refs;
let serial = 500;
function q(subject: string, system: string, topic: string, stem: string, answer: string, explanation: string, wrong: [string,string][], objective: string, ref: Ref = 'clinical', reasoning: 'application'|'integration'|'prioritization' = 'integration'): ExpansionSpec {
 const nearest = subject === 'Pediatrics' ? 'Batch 08 pediatric dehydration, croup localization, coarctation, pyloric acid-base change and intussusception mechanism' : subject === 'Obstetrics' ? 'Batch 08 ectopic site, previa identification, abruption mechanism, preeclampsia mechanism and uterine atony mechanism' : 'Batch 08 surgical recognition and mechanism items, including obstruction, ischemia, hernia and fracture vascular risk';
 return {code: `op26x-${String(++serial).padStart(4,'0')}`, concept: topic.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/-$/,''), reasoning, difficultyReason: `${reasoning === 'prioritization' ? 'Prioritize the stated action with the clinical constraints' : reasoning === 'application' ? 'Apply the stated disease principle to the vignette' : 'Combine the independent clinical findings to distinguish alternatives'}: ${objective}`, evidenceNote: `${refs[ref][0]}: publisher/official indexed record checked 2026-10-29. Supports disease framework or clinical examination; book-level references do not independently validate every option. Older books are not used to assert a current drug regimen.`, semanticReviewNote: `Compared with ${nearest}; distinct objective: ${objective}`, concerns: [], question: {subject,system,topic,stem,options:[[answer,explanation],...wrong],explanation,objective,reference:refs[ref],exam:'Step 2 CK',difficulty:{application:2,integration:3,prioritization:4}[reasoning]}};
}
export const specs: ExpansionSpec[] = [
q('Pediatrics','Respiratory','Bronchiolitis antibiotic stewardship','A previously well 7-month-old has two days of coryza followed by diffuse wheezing, mild retractions and adequate feeding. Oxygenation is normal and there is no focal bacterial infection. Which approach is appropriate?', 'Supportive care without routine antibiotics', 'This first wheezing illness after coryza in an infant fits uncomplicated viral bronchiolitis. Adequate feeding and oxygenation support supportive care; antibiotics do not treat the viral process and require a separate bacterial indication.', [['Oral amoxicillin for every wheezing infant','Wheezing after coryza does not establish bacterial infection.'],['Routine azithromycin to shorten viral shedding','Antibiotics have no routine role in uncomplicated bronchiolitis.'],['Daily antibiotic prophylaxis through winter','Prophylaxis exposes this infant to harm without this indication.']], 'Use respiratory pattern and absence of a bacterial focus to avoid unnecessary antibiotics.', 'antibiotic','application'),
q('Pediatrics','Respiratory','Sinusitis double worsening','A 9-year-old improves after five days of a cold, then develops new fever, worsening daytime cough and purulent nasal discharge. There is no orbital swelling or neurologic deficit. Which diagnosis best fits the change?', 'Acute bacterial sinusitis', 'New deterioration after initial improvement is a recognized bacterial sinusitis pattern. Purulent discharge alone is insufficient, but the biphasic course adds important evidence; uncomplicated viral symptoms ordinarily trend toward recovery.', [['Uncomplicated continuously improving viral rhinitis','The new fever and deterioration contradict continued improvement.'],['Allergic rhinitis as the sole explanation','Fever and a biphasic infectious course are not typical allergy.'],['Foreign body aspiration','Aspiration does not best explain renewed purulent nasal symptoms.']], 'Interpret worsening after initial recovery as a bacterial sinusitis pattern.', 'antibiotic'),
q('Pediatrics','General Principles','Otitis media diagnostic threshold','A crying 20-month-old has a mildly red tympanic membrane during a cold. Pneumatic otoscopy shows normal mobility with no effusion or bulging. What conclusion should guide the antibiotic decision?', 'Acute otitis media is not established', 'A red membrane can reflect crying or a viral illness. Acute otitis media requires middle-ear effusion with appropriate inflammatory findings; normal mobility without effusion or bulging prevents diagnosing it from redness alone.', [['Redness alone confirms bacterial otitis media','Redness is nonspecific without evidence of middle-ear effusion.'],['Every cold requires treatment for occult otitis','Upper respiratory infection alone is not an antibiotic indication.'],['Normal mobility demonstrates a purulent effusion','Fluid generally reduces mobility rather than preserving it.']], 'Require effusion rather than membrane redness alone for acute otitis media.', 'antibiotic','application'),
q('Pediatrics','General Principles','Otitis conjunctivitis antibiotic selection','A 3-year-old has painful bulging tympanic membranes with middle-ear effusions and purulent conjunctivitis. He has no penicillin allergy and needs an oral antibiotic. Which choice best covers the likely beta-lactamase-producing pathogen?', 'Amoxicillin-clavulanate', 'Concurrent purulent conjunctivitis with definite acute otitis media raises concern for beta-lactamase-producing organisms such as nontypeable Haemophilus influenzae. Clavulanate provides beta-lactamase inhibition that amoxicillin alone lacks.', [['Amoxicillin without a beta-lactamase inhibitor','Concurrent purulent conjunctivitis favors broader beta-lactamase coverage.'],['No treatment despite severe bilateral ear pain','This established symptomatic infection differs from isolated membrane redness.'],['Topical eye drops alone','Eye drops do not treat the established middle-ear infection.']], 'Use conjunctivitis as a constraint on antibiotic choice in established otitis media.', 'antibiotic','prioritization'),
q('Pediatrics','Respiratory','Negative streptococcal rapid test','An 8-year-old has fever, tonsillar exudates and tender anterior cervical nodes without cough. A rapid group A streptococcal antigen test is negative. No antibiotic has been given. What test should follow?', 'Throat culture', 'In children with a compatible pharyngitis syndrome, a negative rapid antigen test is backed up by culture because rapid antigen sensitivity is imperfect. Clinical findings guide testing but cannot reliably prove streptococcal infection by themselves.', [['No further testing because rapid sensitivity is perfect','Negative rapid antigen results can miss infection in children.'],['Antistreptolysin O titer to diagnose the acute episode','Antibody responses are delayed and do not replace throat testing.'],['Chest CT to identify tonsillar bacteria','Thoracic imaging does not resolve an acute pharyngeal diagnosis.']], 'Account for imperfect rapid antigen sensitivity when testing a symptomatic child.', 'antibiotic','application'),
q('Pediatrics','Respiratory','Common cold secretion color','A 6-year-old has four days of rhinorrhea and cough. Discharge has become yellow, but fever has resolved, activity is normal and there is no focal examination abnormality. Which interpretation is best?', 'Discharge color alone does not justify antibiotics', 'Colored nasal secretions can occur during a self-limited viral upper respiratory infection. The short, improving course lacks persistent, severe or double-worsening bacterial sinusitis criteria; secretion color does not establish bacterial disease.', [['Yellow mucus proves a bacterial sinus infection','Color is nonspecific during an otherwise improving viral illness.'],['Every colored discharge requires a throat culture','Throat culture evaluates selected pharyngitis presentations, not mucus color.'],['Antibiotics prevent all secondary ear infections','Routine treatment of colds does not justify antibiotic exposure.']], 'Separate nonspecific mucus color from validated bacterial infection patterns.', 'antibiotic','application'),
q('Pediatrics','Cardiovascular','Large ventricular septal defect pulmonary flow','A 2-month-old has sweating with feeds, poor weight gain and tachypnea. Echocardiography shows a large ventricular septal defect with left-to-right flow. Which process primarily explains the respiratory symptoms?', 'Excess pulmonary blood flow', 'After pulmonary resistance falls in early infancy, a large ventricular communication allows substantial left-to-right flow. Increased pulmonary circulation and cardiac volume work cause feeding intolerance and tachypnea rather than primary airway infection.', [['Reduced pulmonary flow from right ventricular obstruction','The described left-to-right defect increases pulmonary flow instead.'],['Isolated obstruction to nasal airflow','This cannot account for the hemodynamically significant septal shunt.'],['Mandatory right-to-left shunting from birth','Shunt direction depends on pressure and resistance, not the name alone.']], 'Connect infant feeding failure to pulmonary overcirculation through a large ventricular defect.', 'heart'),
q('Pediatrics','Cardiovascular','Atrial septal defect chamber burden','A school-age child has a fixed split second heart sound. Echocardiography shows a secundum atrial septal defect and left-to-right flow. Which chambers bear the main chronic volume burden?', 'Right atrium and right ventricle', 'Blood crossing from the left atrium enters the right-sided circulation, increasing right atrial and ventricular volume and pulmonary flow. This explains right chamber dilation; it is not equivalent to a primary obstructive left-heart lesion.', [['Left atrium and left ventricle exclusively','The atrial shunt diverts additional volume into the right heart.'],['Only the systemic aorta','The excess shunted volume first traverses the right heart and lungs.'],['Neither ventricle under any circumstances','A significant atrial shunt can produce right ventricular dilation.']], 'Trace atrial shunt flow to identify the chamber volume burden.', 'heart'),
q('Pediatrics','Cardiovascular','Patent ductus flow direction','A premature infant has a continuous murmur and bounding pulses. Doppler demonstrates an open channel between the descending aorta and pulmonary artery after pulmonary resistance has fallen. Which direction is expected?', 'Aorta to pulmonary artery', 'Systemic aortic pressure normally exceeds pulmonary arterial pressure after pulmonary vascular resistance falls. A persistent ductus then conducts a left-to-right shunt, increasing pulmonary flow and permitting diastolic runoff that widens pulse pressure.', [['Pulmonary artery to aorta in every infant','Ductal flow direction depends on the pressure relationship.'],['Left ventricle directly to right atrium','That is not the anatomic connection described by a ductus.'],['Pulmonary vein to vena cava','That connection represents anomalous venous return, not a ductus.']], 'Infer postnatal ductal flow from the pressure gradient and anatomic connection.', 'heart','application'),
q('Pediatrics','Cardiovascular','Transposition parallel circulations','A cyanotic newborn has the aorta arising from the right ventricle and the pulmonary artery from the left ventricle. Why is an interatrial or ductal communication important before definitive correction?', 'It permits mixing between parallel circulations', 'Discordant great-artery connections send systemic venous blood back to the body and pulmonary venous blood back to the lungs. Survival requires some mixing of these parallel circuits; a communication improves systemic oxygen delivery without correcting the anatomy.', [['It eliminates all need for definitive correction','Mixing supports oxygenation but does not normalize arterial connections.'],['It forces the pulmonary veins to drain into the liver','An interatrial or ductal connection does not reroute venous anatomy.'],['It closes both systemic and pulmonary circuits','Closure of mixing pathways can worsen hypoxemia in transposition.']], 'Explain the role of mixing in transposition rather than treating the circuits as serial.', 'heart'),
q('Pediatrics','Cardiovascular','Tetralogy cyanosis determinant','An infant has a large ventricular septal defect, an overriding aorta and right ventricular hypertrophy. The degree of cyanosis increases as right ventricular outflow obstruction worsens. Which change explains this?', 'More right-to-left ventricular shunting', 'Increasing obstruction to pulmonary outflow makes blood more likely to cross the ventricular communication into the overriding aorta. Systemic delivery of less oxygenated blood rises; the ventricular defect alone does not specify the severity of cyanosis.', [['More oxygenated blood returning exclusively to the lungs','Reduced pulmonary outflow decreases rather than improves oxygenation.'],['Complete elimination of the ventricular pressure gradient','The obstruction raises the right-sided pressure burden.'],['Selective obstruction of pulmonary venous return','Tetralogy involves right ventricular outflow rather than pulmonary venous blockage.']], 'Relate outflow obstruction to shunt direction and cyanosis in tetralogy.', 'heart'),
q('Pediatrics','Gastrointestinal','Hirschsprung rectal biopsy','A term newborn has not passed meconium by 48 hours, develops distention and bilious emesis, and releases stool explosively after rectal examination. Which finding on an appropriately obtained rectal biopsy supports the diagnosis?', 'Absent enteric ganglion cells', 'Distal aganglionosis prevents normal relaxation and creates a functional obstruction with dilation proximally. Delayed meconium and explosive decompression fit Hirschsprung disease; biopsy establishes the innervation defect rather than a primary mucosal malabsorption disorder.', [['Villous atrophy without aganglionosis','Villous injury does not explain congenital distal functional obstruction.'],['Pyloric muscle hypertrophy','This produces proximal nonbilious vomiting and is not a rectal lesion.'],['Normal ganglia with isolated lactase deficiency','Lactase deficiency causes osmotic symptoms rather than this neonatal obstruction.']], 'Connect neonatal distal obstruction to aganglionosis on rectal biopsy.', 'pediatric'),
q('Pediatrics','Gastrointestinal','Biliary atresia cholestasis','A 5-week-old has jaundice persisting beyond the newborn period, dark urine and repeatedly pale stools. Direct bilirubin is elevated. Which diagnosis must be evaluated promptly rather than labeling this physiologic jaundice?', 'Biliary atresia', 'Persistent conjugated jaundice with acholic stools indicates impaired bile delivery to the intestine. Biliary atresia is a time-sensitive cause of neonatal cholestasis; physiologic or breast-milk jaundice is predominantly unconjugated and does not explain acholic stool.', [['Physiologic unconjugated jaundice','This does not account for conjugated hyperbilirubinemia and pale stools.'],['Uncomplicated breast-milk jaundice','Dark urine and acholic stools require a cholestasis evaluation.'],['Isolated iron deficiency anemia','Anemia does not explain direct bilirubin elevation with absent stool pigment.']], 'Distinguish neonatal cholestasis from benign unconjugated jaundice.', 'pediatric'),
q('Pediatrics','Gastrointestinal','Necrotizing enterocolitis pneumatosis','A premature infant receiving enteral feeds develops abdominal distention, bloody stool and temperature instability. A radiograph demonstrates gas within the intestinal wall. Which diagnosis best integrates these findings?', 'Necrotizing enterocolitis', 'Pneumatosis intestinalis in a sick premature infant with feeding intolerance and bloody stool strongly supports necrotizing enterocolitis. The combination suggests bowel injury rather than simple reflux; deterioration or perforation requires urgent multidisciplinary assessment.', [['Uncomplicated gastroesophageal reflux','Reflux does not explain intramural bowel gas and systemic instability.'],['Infantile colic','Colic occurs without inflammatory bowel findings or bloody stool.'],['Simple lactose intolerance','Malabsorption does not usually cause this radiographic injury pattern.']], 'Integrate prematurity, intestinal bleeding and intramural gas to identify bowel injury.', 'pediatric'),
q('Pediatrics','Gastrointestinal','Duodenal atresia bilious vomiting','A newborn develops bilious vomiting shortly after the first feed. Radiography shows two enlarged proximal gas bubbles and no distal intestinal gas. Which structural lesion is most likely?', 'Duodenal atresia', 'A double-bubble pattern with absent distal gas indicates complete proximal intestinal obstruction, commonly duodenal atresia. Bile in the emesis places the obstruction beyond bile entry; pyloric obstruction instead causes nonbilious vomiting.', [['Hypertrophic pyloric stenosis','Pyloric obstruction is proximal to bile entry and usually presents later.'],['Uncomplicated milk reflux','Reflux does not produce absent distal gas from complete obstruction.'],['Distal anal fissure','A superficial anal lesion cannot explain proximal bilious obstruction.']], 'Use bile content and absent distal gas to localize congenital intestinal obstruction.', 'pediatric'),
q('Pediatrics','Renal','Postinfectious nephritis complement','A 7-year-old develops cola-colored urine, periorbital edema and hypertension two weeks after impetigo. Urinalysis shows erythrocyte casts and serum C3 is low. Which diagnosis is most consistent?', 'Poststreptococcal glomerulonephritis', 'A latent interval after skin infection, nephritic sediment and complement consumption fit poststreptococcal glomerulonephritis. Hematuria concurrent with respiratory symptoms favors IgA nephropathy instead; isolated lower urinary infection does not cause red-cell casts.', [['IgA nephropathy with typical synpharyngitic timing','The delayed post-skin-infection course and low C3 favor another cause.'],['Uncomplicated cystitis','Lower urinary infection does not explain casts, edema and low complement.'],['Minimal change nephrotic syndrome','That usually produces heavy proteinuria rather than this nephritic pattern.']], 'Distinguish delayed complement-consuming nephritis from synpharyngitic hematuria.', 'pediatric'),
q('Pediatrics','Renal','Minimal change childhood nephrosis','A 4-year-old develops generalized edema after a minor viral illness. Urine has heavy protein with few cells, albumin is low, kidney function is preserved and complement levels are normal. Which lesion is most likely?', 'Podocyte foot-process effacement', 'The childhood nephrotic pattern with bland sediment and normal complement is typical of minimal change disease. Electron microscopy shows diffuse podocyte foot-process effacement; a proliferative inflammatory glomerular lesion would more often produce a nephritic sediment.', [['Crescent formation in most glomeruli','Crescents suggest severe nephritic injury rather than this bland nephrosis.'],['Linear basement-membrane IgG deposition','Anti-basement-membrane disease usually causes rapidly progressive nephritis.'],['Renal pelvic bacterial pus collections','Pyelonephritis does not produce this isolated nephrotic laboratory pattern.']], 'Infer podocyte injury from a typical childhood nephrotic presentation.', 'pediatric'),
q('Pediatrics','Hematology','Hemolytic uremic syndrome pattern','A 3-year-old becomes pale and oliguric several days after bloody diarrhea. Hemoglobin and platelets are low, creatinine is elevated, schistocytes are present and coagulation times are normal. Which syndrome is most likely?', 'Hemolytic uremic syndrome', 'Microangiopathic hemolysis, thrombocytopenia and acute kidney injury following bloody diarrhea fit typical hemolytic uremic syndrome. Normal coagulation times help distinguish this thrombotic microangiopathy from consumptive disseminated intravascular coagulation.', [['Immune thrombocytopenia alone','Isolated platelet destruction does not explain schistocytes and kidney injury.'],['Hemophilia A','A clotting-factor deficiency does not cause microangiopathic hemolysis.'],['Iron deficiency from restricted diet','Iron deficiency does not explain abrupt thrombocytopenia and renal injury.']], 'Recognize the postdiarrheal thrombotic microangiopathy rather than its toxin mechanism.', 'pediatric'),
q('Pediatrics','Musculoskeletal','Slipped capital femoral epiphysis referred pain','A 13-year-old with obesity reports weeks of knee pain without trauma. The knee examination is normal, but the hip loses internal rotation and externally rotates during flexion. Which site most likely contains the primary pathology?', 'Proximal femoral growth plate', 'Adolescent knee pain can be referred from the hip. Loss of internal rotation with obligatory external rotation in an adolescent with obesity suggests slipped capital femoral epiphysis, a physeal disorder rather than a primary knee cartilage lesion.', [['Tibial tubercle apophysis','That causes local tibial tubercle tenderness rather than restricted hip motion.'],['Patellar articular cartilage alone','A normal knee and abnormal hip examination argue against isolated patellar disease.'],['Lumbar intervertebral disc exclusively','The characteristic hip motion abnormality localizes the concern to the hip.']], 'Identify hip pathology in an adolescent presenting with referred knee pain.', 'clinical'),
q('Pediatrics','Musculoskeletal','Legg Calve Perthes age pattern','A 6-year-old has a painless-to-mildly painful limp for six weeks. Hip abduction and internal rotation are limited, and imaging shows fragmentation and flattening of the femoral head epiphysis. Which process is most likely?', 'Femoral head osteonecrosis', 'Insidious limp and femoral head epiphyseal collapse in a young child suggest Legg-Calve-Perthes disease, caused by impaired epiphyseal blood supply. The age and anatomic location differ from an adolescent proximal femoral physeal slip.', [['Acute bacterial knee infection','The long course and femoral head changes do not localize to the knee.'],['Isolated tibial stress fracture','That does not produce femoral epiphyseal fragmentation.'],['Primary muscle enzyme deficiency','A focal femoral head lesion is not explained by diffuse myopathy.']], 'Distinguish childhood femoral head ischemia from adolescent physeal disease.', 'clinical'),
q('Pediatrics','Musculoskeletal','Septic hip versus transient synovitis','A 5-year-old has fever of 39.5 C, refuses to bear weight and holds the hip flexed. Inflammatory markers are markedly elevated and ultrasound shows a hip effusion. Which action is most appropriate?', 'Urgent joint aspiration and orthopedic assessment', 'Systemic illness, inability to bear weight and a painful effusion raise concern for septic arthritis with potential rapid cartilage damage. Ultrasound identifies fluid but cannot determine sterility; aspiration and urgent assessment are needed rather than assuming transient synovitis.', [['Observe for a week without reassessment','Fever and severe functional loss make delayed evaluation unsafe.'],['Diagnose transient synovitis from the ultrasound alone','An effusion does not distinguish infected from sterile joint fluid.'],['Begin vigorous passive stretching as primary therapy','Manipulation does not address possible infection and may worsen pain.']], 'Prioritize evaluation of a potentially infected hip over benign postviral explanations.', 'pediatric','prioritization'),
q('Pediatrics','Nervous System','Infantile spasms developmental regression','A 6-month-old has clusters of brief symmetric trunk flexion on awakening and has lost previously acquired head control. EEG shows chaotic high-voltage activity with multifocal spikes. Which syndrome best fits?', 'Infantile epileptic spasms syndrome', 'Clustered flexor spasms with developmental regression and a hypsarrhythmic EEG indicate an epileptic encephalopathy. Benign startles do not explain regression or the abnormal background; recognition should prompt urgent specialist evaluation.', [['Benign neonatal sleep myoclonus','That benign sleep-related phenomenon does not explain regression and hypsarrhythmia.'],['Typical absence epilepsy','Absence epilepsy usually presents later with brief staring and generalized spike-wave.'],['Simple febrile seizure','The recurrent afebrile clusters and developmental loss do not fit that diagnosis.']], 'Integrate seizure semiology, developmental regression and EEG background.', 'pediatric'),
q('Pediatrics','Nervous System','Simple febrile seizure classification','A previously healthy 18-month-old has a generalized convulsion lasting three minutes during a fever. He returns fully to baseline, has no meningeal signs and has no second seizure that day. Which classification fits?', 'Simple febrile seizure', 'Age within the usual febrile-seizure range, generalized onset, duration under fifteen minutes and no recurrence within twenty-four hours support a simple febrile seizure. Focality, prolonged duration or same-day recurrence would change the classification.', [['Complex febrile seizure due to duration alone','A three-minute generalized event is not prolonged by the usual definition.'],['Established epilepsy after one fever-associated seizure','A single provoked febrile event does not establish epilepsy.'],['Infantile spasms','A single generalized febrile convulsion lacks clustered brief spasms and regression.']], 'Apply duration, focality and recurrence criteria to a febrile seizure.', 'pediatric','application'),
q('Pediatrics','Nervous System','Spinal muscular atrophy localization','A 4-month-old has progressive symmetric weakness, poor head control, tongue fasciculations and absent tendon reflexes. Alertness and visual interaction are preserved. Which motor structure is primarily affected?', 'Spinal anterior horn motor neurons', 'Weakness with fasciculations and areflexia indicates lower motor neuron disease. Preserved social interaction and the infantile symmetric pattern support spinal muscular atrophy; a primary upper motor neuron process would more often cause hyperreflexia.', [['Cerebral corticospinal tracts exclusively','An isolated upper motor neuron lesion does not explain fasciculations and areflexia.'],['Neuromuscular sensory receptors alone','A sensory receptor defect does not account for tongue fasciculations.'],['Cerebellar Purkinje cells','Cerebellar dysfunction produces coordination abnormalities rather than denervation.']], 'Localize infantile weakness with tongue fasciculations and areflexia.', 'clinical'),
q('Pediatrics','General Principles','Kwashiorkor edema distinction','A recently weaned child has poor growth, bilateral pitting edema, flaky skin changes and sparse discolored hair. Food insecurity is documented. Which malnutrition phenotype is best supported?', 'Edematous severe acute malnutrition', 'Bilateral nutritional edema is a defining feature of edematous severe acute malnutrition, traditionally called kwashiorkor. Edema can conceal wasting on body weight alone; the clinical classification requires excluding other causes such as renal and cardiac disease.', [['Normal nutrition because edema increases weight','Fluid accumulation can mask rather than correct tissue wasting.'],['Isolated marasmus without edema','Marasmus describes severe wasting without the defining nutritional edema.'],['Simple constitutional short stature','That does not explain edema and characteristic skin and hair changes.']], 'Recognize nutritional edema as severe malnutrition even when measured weight is misleading.', 'pediatric'),
q('Pediatrics','General Principles','Dehydration oral versus intravenous route','A 2-year-old with diarrhea is alert, drinks eagerly, has mild mucosal dryness and normal peripheral perfusion. There is no ileus or persistent vomiting. Which initial replacement route is most appropriate?', 'Oral rehydration solution', 'A child who can drink and lacks shock or a contraindication to enteral treatment can generally replace mild-to-moderate losses orally. Glucose-electrolyte solution supports intestinal absorption; routine intravenous treatment adds invasiveness without a stated need.', [['Immediate central venous catheterization for every diarrheal illness','Stable perfusion and oral tolerance do not require central access.'],['Plain water alone for all replacement','Water alone does not adequately replace ongoing electrolyte losses.'],['Withhold all fluids until diarrhea ceases','Continued gastrointestinal losses require replacement rather than fluid restriction.']], 'Choose the least invasive effective rehydration route using perfusion and oral tolerance.', 'pediatric','application'),
q('Pediatrics','Respiratory','Epiglottitis examination precaution','An ill 4-year-old has high fever, drooling, muffled voice and inspiratory stridor while sitting forward. He becomes distressed when placed supine. Which immediate plan best protects him?', 'Maintain comfort and obtain expert controlled airway assessment', 'Drooling, toxicity and positional distress suggest a threatened supraglottic airway. Agitation or forceful examination can precipitate obstruction; controlled expert airway management takes priority over bedside attempts to visualize the throat.', [['Force the child supine for a tongue-depressor examination','Distress and instrumentation may worsen a critically narrowed airway.'],['Send the child unmonitored for outpatient imaging','A threatened airway requires monitored urgent assessment.'],['Offer a large oral sedative before arranging help','Uncontrolled sedation may reduce airway tone and respiratory drive.']], 'Prioritize controlled airway assessment over provocative examination in suspected supraglottic obstruction.', 'pediatric','prioritization'),
q('Pediatrics','Respiratory','Foreign body unilateral wheeze','A 20-month-old suddenly coughs while eating peanuts and subsequently has persistent unilateral wheeze with reduced right-sided air entry. A plain chest radiograph shows no radiopaque object. Which conclusion is best?', 'Airway foreign body remains likely', 'Abrupt onset during eating and persistent asymmetric findings strongly support aspiration. Many food objects are radiolucent, so lack of a visible object does not exclude obstruction; the history warrants specialist airway assessment.', [['A normal visible-object search excludes aspiration','Food foreign bodies often cannot be seen directly on plain radiographs.'],['Symmetric viral bronchiolitis is established','The sudden choking episode and unilateral findings argue against that pattern.'],['The child must have congenital heart disease','A choking-associated asymmetric wheeze localizes primarily to the airway.']], 'Retain aspiration in the differential despite a radiolucent chest film.', 'pediatric'),
q('Pediatrics','Respiratory','Pertussis infant apnea','A 6-week-old has repeated episodes of apnea and cyanosis after a household contact develops prolonged paroxysmal cough. The infant has little fever and no classic inspiratory whoop. Which infection remains concerning?', 'Bordetella pertussis infection', 'Young infants with pertussis may present with apnea rather than a conspicuous whoop. Household exposure and minimal fever support the diagnosis; absence of the classic sound should not provide reassurance in this vulnerable age group.', [['Pertussis is excluded without an audible whoop','Infants may lack the classic whoop and instead develop apnea.'],['Uncomplicated allergic rhinitis','Allergic nasal symptoms do not account for this infectious exposure and apnea.'],['Acute rheumatic fever','This is not a typical manifestation of a poststreptococcal immune syndrome.']], 'Recognize an age-specific pertussis presentation without relying on a whoop.', 'pediatric'),
q('Pediatrics','Dermatology','Roseola fever rash sequence','A 10-month-old has three days of high fever but remains interactive between fever spikes. The fever resolves abruptly, then a blanching pink truncal rash appears. Which diagnosis best fits this sequence?', 'Roseola infantum', 'Defervescence followed by a truncal exanthem is characteristic of roseola. The temporal relationship is more discriminating than the nonspecific rash alone; measles typically has prominent respiratory symptoms and fever continuing with the rash.', [['Measles with typical clinical evolution','Measles usually has cough, coryza and conjunctivitis with ongoing fever.'],['Scarlet fever','That usually accompanies streptococcal pharyngitis with a sandpaper-like rash.'],['Varicella','Varicella produces vesicles in successive crops rather than this fever-rash sequence.']], 'Use the fever-to-rash sequence to distinguish common childhood exanthems.', 'pediatric'),
q('Pediatrics','Dermatology','Kawasaki multisystem clues','A 3-year-old has six days of fever, bilateral nonpurulent conjunctival injection, cracked lips, a swollen cervical node and red swollen hands. Which complication is the principal reason to assess the coronary arteries?', 'Coronary artery aneurysm', 'The prolonged fever and mucocutaneous findings support Kawasaki disease, a medium-vessel vasculitis. Coronary inflammation can lead to aneurysms and later thrombosis; absence of chest pain does not eliminate this pediatric vascular risk.', [['Rupture of a cerebral berry aneurysm as the defining risk','The characteristic vascular complication involves the coronary arteries.'],['Permanent mitral stenosis from rheumatic scarring','That follows a different immune-mediated disease pattern.'],['Isolated venous valve failure','Kawasaki disease primarily threatens arterial rather than venous structures.']], 'Identify the coronary consequence of a pediatric mucocutaneous vasculitis pattern.', 'pediatric'),
q('Pediatrics','Dermatology','IgA vasculitis abdominal renal pattern','A 7-year-old has palpable purpura over the legs and buttocks, ankle pain and colicky abdominal pain after a respiratory illness. Platelets are normal and urine contains blood and protein. Which mechanism fits?', 'IgA-mediated small-vessel inflammation', 'Nonthrombocytopenic palpable purpura with joint, intestinal and renal involvement supports IgA vasculitis. The systemic distribution distinguishes it from isolated immune platelet destruction; kidney involvement requires follow-up even when the rash improves.', [['Isolated immune destruction of platelets','The normal platelet count and renal involvement argue against isolated ITP.'],['Vitamin K deficiency as the sole lesion','A coagulation-factor deficiency does not explain this palpable vasculitic pattern.'],['Local insect bites without systemic disease','The associated abdominal, joint and urinary findings indicate a systemic process.']], 'Integrate normal platelets with skin, joint, intestinal and renal findings.', 'pediatric'),
q('Pediatrics','Endocrine','Congenital hypothyroidism screening rationale','A newborn appears well but has an abnormal thyroid screening result. Confirmatory testing shows low free thyroxine and markedly elevated TSH. Why should evaluation proceed promptly despite few symptoms?', 'Early hormone deficiency can impair brain development', 'Clinical signs may be subtle in early congenital hypothyroidism, partly because of maternal hormone exposure. Adequate thyroid hormone is essential for early neurodevelopment; a normal-looking infant does not invalidate the biochemical primary hypothyroid pattern.', [['All affected newborns are obviously symptomatic at birth','Early signs may be subtle and screening identifies otherwise missed cases.'],['Elevated TSH proves excessive thyroid hormone action','High TSH with low free thyroxine indicates insufficient thyroid effect.'],['Brain development is independent of thyroid hormone','Early neurodevelopment is sensitive to thyroid hormone deficiency.']], 'Explain the value of prompt biochemical detection before overt neonatal symptoms.', 'pediatric'),
q('Pediatrics','Endocrine','Salt wasting congenital adrenal hyperplasia','A 12-day-old has vomiting, weight loss, dehydration, sodium 121 mEq/L and potassium 6.8 mEq/L. The genital examination shows virilization in an infant with a 46,XX karyotype. Which enzyme deficiency best integrates the findings?', '21-hydroxylase deficiency', 'Impaired cortisol and aldosterone synthesis causes salt wasting, while accumulated precursors increase adrenal androgen production and virilization. The combined electrolyte and genital findings distinguish 21-hydroxylase deficiency from androgen resistance or isolated thyroid disease.', [['Complete androgen insensitivity','That does not explain salt-wasting mineralocorticoid deficiency in a 46,XX infant.'],['11-beta-hydroxylase deficiency with its usual mineralocorticoid effect','Accumulated deoxycorticosterone usually promotes hypertension rather than salt wasting.'],['Thyroid peroxidase deficiency','Thyroid hormone synthesis failure does not produce adrenal androgen excess.']], 'Combine adrenal electrolyte failure with androgen excess to distinguish steroid defects.', 'pediatric'),
q('Pediatrics','General Principles','Developmental regression versus delay','A 16-month-old who previously used five meaningful words and walked independently now uses no words and cannot rise without help. Hearing testing is normal. Which description best captures the developmental concern?', 'Regression of acquired skills', 'Loss of previously established language and motor abilities is regression, not simply delayed acquisition. Involvement of multiple domains warrants evaluation for neurologic or systemic disease; normal hearing does not explain the motor loss or exclude other causes.', [['Isolated expressive language delay','Loss of established walking skills indicates more than an isolated language problem.'],['Normal variation requiring no assessment','Loss of established abilities is a significant developmental warning sign.'],['A diagnosis of autism proved by this history alone','Regression has multiple causes and requires a broader diagnostic assessment.']], 'Distinguish loss of acquired skills from a static developmental delay.', 'pediatric','application'),
q('Obstetrics','Pregnancy','Pregnancy unknown location stable followup','A stable patient has a positive pregnancy test and mild spotting. Ultrasound shows neither an intrauterine nor an adnexal pregnancy. There is no free fluid or focal tenderness. What interpretation is most appropriate?', 'Pregnancy location remains undetermined', 'A nondiagnostic early ultrasound does not by itself prove ectopic pregnancy or completed miscarriage. Serial clinical assessment, hCG measurements and repeat ultrasound are needed; new pain or instability would change the urgency.', [['Ectopic pregnancy is definitively established','Absence of a visible intrauterine sac alone does not establish ectopic location.'],['A completed miscarriage is definitively established','No prior documented intrauterine pregnancy or passage history establishes that conclusion.'],['Follow-up is unnecessary because vital signs are normal','An initially stable pregnancy of unknown location still requires follow-up.']], 'Separate nondiagnostic early imaging from a definitive location diagnosis.', 'ectopic'),
q('Obstetrics','Pregnancy','Threatened pregnancy loss viability','At 9 weeks a patient has light spotting, no pain and a closed cervical os. Ultrasound confirms an intrauterine embryo with cardiac activity. Which interpretation best fits the evidence?', 'Bleeding with a currently viable intrauterine pregnancy', 'Cardiac activity establishes current viability and the closed os distinguishes threatened loss from an actively progressing miscarriage. Bleeding alone does not demonstrate pregnancy loss, although follow-up is appropriate and future outcome cannot be guaranteed.', [['Completed miscarriage','An intrauterine embryo with cardiac activity contradicts completed loss.'],['Anembryonic pregnancy','A visualized embryo excludes an empty gestational sac diagnosis.'],['Ruptured tubal ectopic pregnancy','The stable painless presentation with intrauterine viability does not fit rupture.']], 'Interpret first-trimester bleeding using cervical findings and documented viability.', 'loss'),
q('Obstetrics','Pregnancy','Early pregnancy ultrasound uncertainty','At an estimated 5 weeks by an uncertain last menstrual period, ultrasound shows a small intrauterine gestational sac without an embryo. The patient is stable and wants the pregnancy. What is the best conclusion?', 'The scan may be too early to determine viability', 'Uncertain dating and an early small sac without an embryo cannot reliably establish pregnancy failure. Repeat ultrasound using validated intervals and criteria avoids ending a potentially viable pregnancy on a single nondiagnostic scan.', [['Absent embryo at any estimated age proves miscarriage','Early gestations may precede visible embryonic development.'],['Ectopic pregnancy is proven by the empty uterine sac','The described finding does not establish an extrauterine implantation.'],['A normal future pregnancy outcome is guaranteed','Early nondiagnostic imaging does not guarantee subsequent viability.']], 'Avoid diagnosing early pregnancy failure from an inadequately timed single scan.', 'loss','application'),
q('Obstetrics','Pregnancy','Ruptured ectopic hemodynamic priority','A patient at 7 weeks has sudden pelvic pain, syncope, hypotension and a positive pregnancy test. Bedside ultrasound shows free intraperitoneal fluid and no intrauterine pregnancy. What management priority fits this situation?', 'Resuscitation and urgent operative assessment', 'Shock with free fluid and suspected ectopic pregnancy raises concern for life-threatening intra-abdominal hemorrhage. Stabilization and urgent surgical management take priority over serial outpatient testing or a medical regimen requiring a stable unruptured pregnancy.', [['Discharge for a repeat hCG level in two days','Hemodynamic instability makes outpatient serial testing inappropriate.'],['Routine methotrexate without surgical assessment','Suspected rupture and shock are incompatible with routine medical treatment.'],['Delay all treatment until an exact hCG threshold is reached','An unstable hemorrhagic presentation must not wait for a numeric threshold.']], 'Use instability and intraperitoneal fluid to prioritize hemorrhage control.', 'ectopic','prioritization'),
q('Obstetrics','Pregnancy','Vasa previa fetal hemorrhage','Immediately after membrane rupture, painless vaginal bleeding occurs and the fetal heart rate falls profoundly. Maternal blood pressure remains normal. Ultrasound earlier showed fetal vessels crossing near the internal os. Which process is most likely?', 'Rupture of unprotected fetal vessels', 'Vasa previa places fetal vessels in the membranes over or near the cervix. Rupture can cause rapid fetal blood loss and bradycardia while maternal hemodynamics remain preserved, distinguishing it from predominantly maternal hemorrhage.', [['Maternal uterine atony before delivery','Atony causes postpartum maternal bleeding rather than vessel rupture with membranes.'],['Benign cervical mucus passage','Profound fetal bradycardia and known exposed vessels are not benign bloody show.'],['Physiologic fetal heart slowing without blood loss','The immediate bleeding after rupture supports fetal vessel injury.']], 'Distinguish fetal from maternal hemorrhage using membrane rupture and discordant vital signs.', 'pregnancy'),
q('Obstetrics','Pregnancy','Placenta accreta risk anatomy','A patient with two previous cesarean births has an anterior placenta previa. Imaging suggests placental villi attach directly to myometrium because the normal intervening decidua is deficient. Which disorder is suspected?', 'Placenta accreta spectrum', 'Prior uterine surgery combined with placenta previa raises concern for abnormal placental adherence at a scarred implantation site. Deficient decidual separation permits attachment or invasion into myometrium and creates major hemorrhage risk when separation is attempted.', [['Placental abruption only','Abruption is premature separation rather than abnormal attachment to myometrium.'],['Isolated velamentous cord insertion','Cord insertion anatomy does not explain deficient decidual separation.'],['Simple physiologic placental attachment','Normal decidua permits separation and does not directly tether villi to muscle.']], 'Combine uterine scar and previa with abnormal placental attachment anatomy.', 'pregnancy'),
q('Obstetrics','Pregnancy','Concealed abruption severity','At 35 weeks after blunt trauma, a patient has severe abdominal pain, a tense tender uterus and fetal distress. Visible vaginal bleeding is scant. Why can the severity of hemorrhage exceed what is externally apparent?', 'Blood can remain trapped behind the placenta', 'A retroplacental hematoma may be concealed, so visible bleeding can underestimate blood loss in abruption. Pain, uterine hypertonicity, maternal status and fetal findings matter more than assuming a small external volume excludes severe separation.', [['Every placental bleed must drain externally','Retroplacental blood may remain concealed within the uterus.'],['Fetal distress excludes significant placental separation','Placental separation can directly impair fetal oxygen exchange.'],['A normal-looking external pad proves stable circulation','External blood volume alone cannot measure concealed hemorrhage.']], 'Recognize concealed hemorrhage rather than grading abruption by external blood alone.', 'pregnancy'),
q('Obstetrics','Pregnancy','Gestational hypertension versus preeclampsia','A previously normotensive patient at 30 weeks has repeated blood pressures of 146/92 mm Hg. Platelets, creatinine and transaminases are normal, urine protein is below threshold and there are no severe symptoms. Which classification fits now?', 'Gestational hypertension', 'New hypertension after twenty weeks without proteinuria or qualifying organ dysfunction fits gestational hypertension at this assessment. It requires surveillance because preeclampsia can develop later; edema alone would not establish preeclampsia.', [['Chronic hypertension solely because two readings are high','Chronic hypertension generally predates pregnancy or appears before twenty weeks.'],['Preeclampsia proven by blood pressure alone at this severity','This case lacks proteinuria and qualifying end-organ findings.'],['Normal pregnancy blood pressure','Repeated values at or above 140/90 are abnormal during pregnancy.']], 'Classify new nonsevere hypertension using timing and absence of organ injury.', 'hypertension'),
q('Obstetrics','Pregnancy','Preeclampsia without proteinuria','At 33 weeks a previously normotensive patient develops hypertension, severe persistent right upper quadrant pain, elevated transaminases and platelets of 82,000/microliter. Urine protein is not elevated. What conclusion is correct?', 'Preeclampsia can be diagnosed without proteinuria', 'New hypertension after twenty weeks with thrombocytopenia and hepatic involvement supports preeclampsia with severe features despite absent proteinuria. Requiring protein in every case would miss clinically important multisystem disease.', [['Proteinuria is mandatory in every case','Qualifying end-organ dysfunction can establish the syndrome without proteinuria.'],['Normal urine protein excludes obstetric disease','The hematologic and hepatic abnormalities remain significant severe features.'],['The blood pressure must be chronic','The timing and new organ injury do not establish preexisting hypertension.']], 'Recognize severe organ features as an alternative to proteinuria for preeclampsia.', 'hypertension'),
q('Obstetrics','Pregnancy','HELLP laboratory integration','A patient at 34 weeks has epigastric pain and hypertension. Testing shows schistocytes, elevated LDH, AST 210 U/L and platelets of 61,000/microliter. Which syndrome most directly integrates this combination?', 'HELLP syndrome', 'Hemolysis, elevated liver enzymes and low platelets define HELLP, an important severe pregnancy-associated syndrome. The schistocytes and LDH support hemolysis rather than isolated gestational thrombocytopenia, which does not produce this multisystem injury pattern.', [['Isolated gestational thrombocytopenia','That benign platelet pattern does not explain hemolysis and hepatic injury.'],['Uncomplicated iron deficiency','Iron deficiency does not cause this acute microangiopathic and hepatic combination.'],['Physiologic pregnancy hemodilution','Hemodilution does not explain schistocytes and marked thrombocytopenia.']], 'Combine microangiopathic hemolysis, liver injury and thrombocytopenia.', 'hypertension'),
q('Obstetrics','Pregnancy','Postpartum preeclampsia warning','Five days after delivery, a patient develops severe headache, visual spots and blood pressure of 174/112 mm Hg confirmed on repeat assessment. Pregnancy had previously been normotensive. Which conclusion should guide care?', 'New postpartum preeclampsia remains possible', 'Preeclampsia can first present after childbirth, including after a previously normotensive pregnancy. Severe hypertension and neurologic symptoms require urgent evaluation; delivery does not eliminate all subsequent hypertensive and seizure risk.', [['Delivery permanently excludes preeclampsia','The syndrome can begin in the postpartum period.'],['All postpartum headaches are tension headaches','Severe hypertension and visual symptoms require urgent assessment.'],['Normal antenatal pressure excludes future severe hypertension','An uncomplicated antenatal course does not exclude postpartum disease.']], 'Recognize new postpartum hypertensive disease despite normal antenatal measurements.', 'hypertension'),
q('Obstetrics','Pregnancy','Preeclampsia delivery maternal tradeoff','A patient with severe preeclampsia at 30 weeks asks why delivery is being discussed when prematurity carries risks. Which explanation best describes the central competing considerations?', 'Maternal organ injury must be balanced against fetal prematurity', 'The placenta-associated disease may worsen and threaten maternal or fetal health, while early delivery introduces prematurity risks. Timing depends on stability and gestational age; a fixed promise to continue every pregnancy to term ignores potentially progressive organ injury.', [['Prematurity never has clinically important consequences','Respiratory and other neonatal complications remain important competing risks.'],['Continuing pregnancy to term is always safest for the mother','Severe organ disease may make continued pregnancy dangerous.'],['Every diagnosis requires delivery before any stabilization','Maternal stabilization and individualized timing are integral to management.']], 'Explain competing maternal disease and neonatal prematurity risks without a universal timing rule.', 'hypertension'),
q('Obstetrics','Pregnancy','Gestational diabetes fetal insulin','An infant born to a patient with poorly controlled gestational diabetes develops hypoglycemia shortly after birth. Which prenatal adaptation most directly explains the neonatal glucose fall?', 'Fetal hyperinsulinemia persisting after placental glucose delivery stops', 'Maternal glucose crosses the placenta and stimulates fetal insulin release. At delivery the glucose supply falls abruptly while neonatal insulin remains elevated, producing hypoglycemia; maternal insulin itself does not freely cross the placenta to create this effect.', [['Direct transfer of large amounts of maternal insulin','Maternal insulin is not the main freely transferred driver of fetal hyperinsulinemia.'],['Permanent absence of fetal insulin secretion','Insulin deficiency would favor hyperglycemia rather than this postnatal decline.'],['Excess neonatal glucagon secretion','Glucagon tends to raise rather than lower plasma glucose.']], 'Connect prenatal glucose exposure to postnatal hypoglycemia through fetal insulin.', 'clinical'),
q('Obstetrics','Pregnancy','Hyperemesis versus ordinary nausea','At 10 weeks a patient has persistent vomiting, orthostatic symptoms and loss of 7% of prepregnancy weight. Oral intake is minimal and urine contains ketones. Which diagnosis best fits the severity?', 'Hyperemesis gravidarum', 'Substantial weight loss, dehydration and inability to maintain intake distinguish hyperemesis from common mild pregnancy nausea. Ketosis supports poor intake but is not the sole diagnostic criterion; other causes of severe vomiting still require consideration.', [['Typical mild morning sickness without nutritional impact','Marked weight loss and volume depletion indicate a more severe syndrome.'],['Preeclampsia as the most likely explanation at ten weeks','The timing and absence of hypertension do not support the usual syndrome.'],['Normal physiologic weight loss needing no assessment','Loss of this magnitude with dehydration is not routine pregnancy physiology.']], 'Use nutritional and volume consequences to distinguish severe pregnancy vomiting.', 'clinical'),
q('Obstetrics','Pregnancy','Molar pregnancy early severe manifestations','A patient with vaginal bleeding has a uterus much larger than expected at 11 weeks, markedly elevated hCG and diffuse cystic intrauterine tissue without an embryo. Which diagnosis best unifies the findings?', 'Complete hydatidiform mole', 'Excess trophoblastic proliferation can produce very high hCG, uterine enlargement and a cystic placental pattern without fetal tissue in a complete mole. A normal early gestation does not account for the combined biochemical and imaging abnormalities.', [['Normal singleton pregnancy','The diffuse abnormal tissue and disproportionate findings argue against normal development.'],['Isolated cervical polyp','A cervical lesion does not explain markedly abnormal intrauterine tissue and hCG.'],['Simple ovarian follicular cyst','An isolated ovarian cyst does not produce this uterine trophoblastic pattern.']], 'Integrate excessive hCG, uterine size and absent embryonic tissue in trophoblastic disease.', 'clinical'),
q('Obstetrics','Pregnancy','Uterine rupture intrapartum pattern','During labor after a previous cesarean birth, a patient has sudden abdominal pain, sustained fetal bradycardia and loss of fetal station. Maternal tachycardia develops. Which complication requires immediate consideration?', 'Uterine rupture', 'A scarred uterus with abrupt pain, fetal compromise and loss of station suggests disruption of the uterine wall. These findings are not explained by ordinary contractions; hemorrhage may be concealed and urgent operative assessment is required.', [['Normal progression into the second stage','Loss of station with sustained fetal bradycardia is not reassuring labor progress.'],['Isolated cervical dilation','Dilation alone does not explain abrupt fetal recession and maternal instability.'],['Uncomplicated membrane rupture','That does not account for the full scar-related emergency pattern.']], 'Recognize scar-related uterine disruption from simultaneous maternal and fetal changes.', 'pregnancy'),
q('Obstetrics','Pregnancy','Shoulder dystocia recognition','After the fetal head delivers, it retracts against the perineum and the shoulders fail to deliver with normal gentle traction. Which mechanical event best explains this labor emergency?', 'Anterior fetal shoulder impaction behind the pubic symphysis', 'Failure of shoulder delivery with head retraction suggests shoulder dystocia, commonly involving the anterior shoulder behind the symphysis. The fetal head is already delivered, so the problem differs from cervical obstruction or failure of cephalic descent.', [['An undilated cervix blocking the fetal head','The head has already passed through the fully dilated cervix.'],['Placental attachment to the uterine scar','Placental adherence does not mechanically trap the delivered shoulders.'],['A cord loop causing all cases of head retraction','Cord position does not define this shoulder impaction pattern.']], 'Localize failed shoulder delivery after head emergence to shoulder impaction.', 'clinical'),
q('Obstetrics','Pregnancy','Postpartum laceration versus atony','Heavy bleeding follows a vaginal delivery. The uterus is firm and well contracted, the placenta appears complete and inspection identifies a deep cervical tear. Which source best explains the continued bleeding?', 'Genital tract trauma', 'A firmly contracted uterus makes uterine atony less likely, while a visible cervical tear supplies a direct bleeding source. Postpartum hemorrhage assessment considers tone, trauma, tissue and coagulation rather than treating every case as atony.', [['Uterine atony as the only possible source','The well-contracted uterus and visible tear favor traumatic bleeding.'],['Normal lochia requiring no assessment','Heavy continuing bleeding with a deep tear exceeds normal postpartum discharge.'],['Placenta previa persisting as the intact placenta','The placenta has delivered and a traumatic source is directly visible.']], 'Use uterine tone and direct inspection to distinguish traumatic postpartum bleeding.', 'pregnancy'),
q('Obstetrics','Pregnancy','Retained placenta postpartum bleeding','A patient has continued postpartum bleeding and uterine subinvolution. The delivered placenta has a missing cotyledon, and ultrasound shows intracavitary tissue. Which cause is most consistent?', 'Retained placental tissue', 'An incomplete placenta with persistent intracavitary material supports retained tissue, which interferes with normal uterine contraction and involution. The physical completeness of the placenta is therefore relevant even when initial uterotonic measures have been used.', [['Isolated cervical ectropion','That cannot explain a missing placental segment and intracavitary tissue.'],['Normal complete placental separation','The incomplete placenta contradicts complete removal of placental tissue.'],['A new ectopic pregnancy immediately after birth','The timing and documented retained material favor a postpartum uterine source.']], 'Link placental incompleteness and subinvolution to retained tissue.', 'pregnancy'),
q('Obstetrics','Pregnancy','Postpartum endometritis localization','Three days after cesarean birth, a patient has fever, lower abdominal pain, uterine fundal tenderness and malodorous lochia. The incision is clean and there are no urinary or respiratory symptoms. Which diagnosis best fits?', 'Postpartum endometritis', 'Fever with uterine tenderness and foul lochia localizes infection to the postpartum endometrial cavity. Cesarean delivery increases risk; a clean skin incision does not exclude uterine infection, and urinary infection would require a different localization pattern.', [['Isolated superficial incision cellulitis','The incision is clean and the tenderness is centered on the uterus.'],['Physiologic afterpains alone','Normal uterine cramping does not account for fever and foul lochia.'],['Uncomplicated engorgement as the sole cause','The uterine findings specifically support a pelvic source of infection.']], 'Localize postpartum fever using uterine tenderness and discharge characteristics.', 'clinical'),
q('Obstetrics','Endocrine','Functional hypothalamic amenorrhea','A distance runner has six months of amenorrhea after caloric restriction and increased training. Pregnancy testing is negative, prolactin and TSH are normal, and estradiol and gonadotropins are low. Which process fits?', 'Suppression of hypothalamic GnRH pulsatility', 'Low energy availability can reduce hypothalamic reproductive signaling, causing low gonadotropins and estradiol. The hormone pattern differs from primary ovarian insufficiency, where loss of ovarian feedback usually raises gonadotropins.', [['Primary ovarian failure with high FSH','The low gonadotropins favor central suppression rather than ovarian failure.'],['Autonomous estrogen-secreting ovarian tumor','That would not explain low estradiol and the low-energy context.'],['Normal menopause at any age','The exercise-associated central hormone pattern requires a different explanation.']], 'Use energy history and gonadotropin direction to localize amenorrhea.', 'clinical'),
q('Obstetrics','Endocrine','Primary ovarian insufficiency gonadotropins','A 29-year-old has repeated amenorrhea, hot flashes and vaginal dryness. Pregnancy is excluded; repeated testing shows elevated FSH and low estradiol. Which site is primarily failing?', 'Ovarian follicular function', 'Reduced ovarian estrogen production removes negative feedback and raises FSH. In a patient younger than forty with a sustained compatible pattern, primary ovarian insufficiency is considered; central suppression would generally cause low or inappropriately normal gonadotropins.', [['Hypothalamic GnRH production alone','Central reproductive suppression does not usually generate markedly elevated FSH.'],['An estrogen-producing uterine fibroid','Fibroids are not the usual endocrine source of ovarian feedback failure.'],['Excess pituitary prolactin as demonstrated here','No elevated prolactin is supplied and that mechanism usually suppresses gonadotropins.']], 'Localize low estrogen with elevated FSH to primary ovarian dysfunction.', 'clinical'),
q('Obstetrics','Endocrine','PCOS endometrial exposure','A patient with chronic irregular cycles and hirsutism has a negative pregnancy test and no alternative androgen disorder. Why can prolonged anovulation increase the risk of endometrial hyperplasia?', 'Lack of cyclic progesterone opposition to estrogen', 'Without regular ovulation, a corpus luteum does not reliably supply cyclic progesterone. Continued estrogenic stimulation can therefore promote endometrial proliferation without organized withdrawal; this risk is related to anovulation rather than the appearance of ovarian follicles alone.', [['Excess progesterone continuously suppresses the endometrium','Progesterone normally opposes proliferation rather than causing unopposed estrogen exposure.'],['All ovarian follicles are malignant','Polycystic follicular morphology does not mean ovarian malignancy.'],['Complete absence of estrogenic stimulation','Endometrial proliferation requires estrogenic stimulation, which may persist during anovulation.']], 'Connect chronic anovulation to unopposed endometrial estrogen exposure.', 'bleeding'),
q('Obstetrics','Endocrine','Hyperprolactinemic amenorrhea','A patient has amenorrhea, spontaneous bilateral milk discharge and repeated elevated prolactin. Pregnancy and hypothyroidism are excluded. How does excess prolactin most directly impair ovulation?', 'Suppression of hypothalamic reproductive signaling', 'Hyperprolactinemia interferes with pulsatile hypothalamic GnRH signaling and reduces normal gonadotropin support for ovulation. Galactorrhea and amenorrhea fit this endocrine pattern, though medication effects and pituitary causes require etiologic evaluation.', [['Direct creation of an obstructed cervical canal','The endocrine findings point to an ovulatory rather than mechanical outflow disorder.'],['Persistent maximal stimulation of cyclic LH surges','Excess prolactin suppresses rather than maintains normal ovulatory signaling.'],['Obligatory destruction of every ovarian follicle','The mechanism can be reversible signaling suppression rather than total follicular loss.']], 'Explain ovulatory suppression in hyperprolactinemia without assuming irreversible ovarian loss.', 'clinical'),
q('Obstetrics','Pregnancy','Asherman syndrome postinstrumentation','A patient develops markedly lighter menses and infertility after uterine curettage for retained placental tissue. Pregnancy testing is negative and hysteroscopy demonstrates fibrous bands bridging the uterine cavity. Which diagnosis fits?', 'Intrauterine adhesions', 'Endometrial injury after instrumentation can create intrauterine scar bands, reducing functional cavity space and menstrual flow. The visible adhesions directly support Asherman syndrome rather than a purely ovarian or hypothalamic cause of amenorrhea.', [['Polycystic ovary syndrome alone','A hormonal ovulatory disorder does not explain hysteroscopically visible scar bands.'],['Complete androgen insensitivity','That congenital condition does not explain newly acquired postprocedure changes.'],['Isolated cervical ectropion','Cervical glandular exposure does not create bridging intrauterine adhesions.']], 'Identify an acquired uterine cavity cause of menstrual change and infertility.', 'clinical'),
q('Obstetrics','Pregnancy','Endometriosis extrauterine tissue','A patient has progressive cyclic pelvic pain, deep dyspareunia and infertility. Laparoscopy finds dark lesions on the uterosacral ligaments; biopsy shows endometrial glands and stroma outside the uterus. Which diagnosis is established?', 'Endometriosis', 'Endometrial-type glands and stroma outside the uterine cavity establish endometriosis. Cyclic pain and infertility support the pattern; glands within myometrium instead characterize adenomyosis, which is anatomically distinct despite overlapping pain symptoms.', [['Adenomyosis','That describes endometrial tissue within myometrium rather than extrauterine implants.'],['Uncomplicated uterine leiomyoma','A smooth-muscle tumor does not contain diagnostic ectopic endometrial glands and stroma.'],['Physiologic ovulation pain alone','The biopsy and chronic infertility indicate more than transient ovulatory discomfort.']], 'Distinguish extrauterine endometrial implants from intramyometrial disease.', 'clinical'),
q('Obstetrics','Pregnancy','Adenomyosis diffuse uterine enlargement','A 43-year-old with prior pregnancies has progressively heavy painful menses. Examination shows a diffusely enlarged tender globular uterus, and MRI shows thickening of the junctional zone without a discrete mass. Which diagnosis fits?', 'Adenomyosis', 'Endometrial glands and stroma within myometrium can cause diffuse uterine enlargement, tenderness and heavy painful bleeding. A discrete whorled mass would favor leiomyoma; the diffuse junctional-zone pattern is more consistent with adenomyosis.', [['Pedunculated ovarian cyst','An adnexal cyst does not produce diffuse myometrial junctional-zone thickening.'],['Isolated cervical polyp','A small cervical lesion cannot explain diffuse globular uterine enlargement.'],['Ectopic tubal pregnancy','The chronic cyclic symptoms and myometrial imaging do not fit an acute ectopic gestation.']], 'Differentiate diffuse intramyometrial disease from a focal uterine or adnexal mass.', 'bleeding'),
q('Obstetrics','Pregnancy','Submucosal fibroid bleeding mechanism','A patient with heavy regular menses has a firm irregular uterus. Ultrasound identifies a leiomyoma projecting into the endometrial cavity. Which feature most directly links this lesion to the bleeding?', 'Distortion of the endometrial cavity', 'Submucosal leiomyomas alter the endometrial cavity and can increase bleeding through changes in surface area and local hemostasis. The relation to the cavity is more relevant to heavy menses than assuming every fibroid behaves identically regardless of location.', [['All fibroids are estrogen-secreting cancers','Leiomyomas are benign smooth-muscle tumors rather than hormone-secreting cancers.'],['Direct obstruction of the pulmonary artery','That mechanism does not connect an intracavitary uterine lesion to menstrual bleeding.'],['Complete suppression of endometrial growth','Suppressed growth would not explain the heavy regular bleeding pattern.']], 'Use fibroid relationship to the cavity to explain heavy menstrual bleeding.', 'bleeding'),
q('Obstetrics','Pregnancy','Postmenopausal bleeding diagnostic priority','A 63-year-old reports new painless vaginal bleeding two years after menopause. She takes no hormone therapy. Examination reveals no traumatic or cervical bleeding source. Which principle should guide the evaluation?', 'Evaluate for endometrial disease including malignancy', 'Postmenopausal bleeding is abnormal and can reflect endometrial cancer or precancer, even when painless and small in volume. Benign causes are common, but symptom severity alone does not safely exclude malignancy or justify attributing the bleeding to renewed ovulation.', [['Assume normal ovulatory menses have resumed','Bleeding after established menopause requires evaluation rather than that assumption.'],['Exclude endometrial cancer because there is no pain','Early endometrial malignancy may present with painless bleeding.'],['Diagnose cancer from the symptom alone','Bleeding warrants investigation but does not by itself prove malignancy.']], 'Recognize postmenopausal bleeding as an evaluation trigger without prematurely assigning a diagnosis.', 'bleeding','application'),
q('Obstetrics','Pregnancy','Imperforate hymen outflow obstruction','A 14-year-old has normal breast development, monthly lower abdominal pain and no menarche. Examination reveals a bulging bluish hymenal membrane; ultrasound shows blood distending the vagina. What explains the amenorrhea?', 'Obstruction of menstrual outflow', 'Normal pubertal estrogenization with cyclic pain and hematocolpos indicates menstrual production behind an obstructed outflow tract. An imperforate hymen differs from central or ovarian endocrine failure, which would not usually create cyclic retained vaginal blood.', [['Absent ovarian estrogen production','Normal breast development and accumulated cyclic blood argue against estrogen absence.'],['Complete lack of uterine development','A uterus producing retained menstrual blood is present in this case.'],['Physiologic absence of all menstrual shedding','Cyclic retained blood demonstrates that shedding is occurring.']], 'Distinguish an anatomic outflow defect from endocrine causes of primary amenorrhea.', 'clinical'),
q('Obstetrics','Pregnancy','Mullerian agenesis versus androgen insensitivity','A 17-year-old with primary amenorrhea has normal breasts and normal pubic hair. Imaging shows absent uterus but normal ovaries, and karyotype is 46,XX. Which diagnosis best integrates these findings?', 'Mullerian agenesis', 'Absent uterine development with functional ovaries, normal pubic hair and a 46,XX karyotype supports Mullerian agenesis. Complete androgen insensitivity usually involves a 46,XY karyotype, testes and sparse androgen-dependent hair rather than normal ovaries.', [['Complete androgen insensitivity','The 46,XX karyotype and normal ovaries contradict the typical androgen-insensitivity pattern.'],['Functional hypothalamic amenorrhea','Central hormonal suppression does not cause congenital absence of the uterus.'],['Imperforate hymen','That outflow defect retains a uterus and may cause hematocolpos.']], 'Integrate karyotype, pubic hair and gonadal anatomy in primary amenorrhea.', 'clinical'),
q('Obstetrics','Pregnancy','Ovarian torsion preserved Doppler flow','A patient with a known ovarian cyst develops abrupt unilateral pelvic pain and vomiting. The ovary is enlarged, but Doppler still detects arterial flow. Which interpretation is best?', 'Torsion remains possible despite arterial flow', 'Dual ovarian blood supply and intermittent or partial twisting can preserve detectable arterial flow during torsion. Sudden pain with an enlarged at-risk ovary requires urgent evaluation; Doppler perfusion alone does not reliably exclude the diagnosis.', [['Arterial flow definitively rules out torsion','Preserved flow can occur with partial, intermittent or dual-supply perfusion.'],['The cyst must be malignant because it is painful','Acute pain does not establish histology or malignant behavior.'],['Vomiting proves the pain is unrelated to the adnexa','Visceral adnexal emergencies can provoke nausea and vomiting.']], 'Avoid falsely excluding adnexal torsion on the basis of preserved Doppler flow.', 'clinical'),
q('Obstetrics','Pregnancy','Ruptured functional cyst stable patient','A patient develops unilateral pelvic pain shortly after intercourse at midcycle. Pregnancy testing is negative, vital signs remain normal, hemoglobin is stable and ultrasound shows a small collapsed ovarian cyst with limited free fluid. Which diagnosis fits?', 'Ruptured functional ovarian cyst', 'A collapsed cyst with limited pelvic fluid after abrupt pain supports cyst rupture in a stable nonpregnant patient. Ectopic pregnancy is less likely with a negative test, while progressive instability or falling hemoglobin would require a different level of concern.', [['Ruptured ectopic pregnancy established despite a negative test','The available pregnancy testing and ovarian findings favor a functional cyst complication.'],['Complete bowel obstruction','There is no vomiting, obstipation or obstructive imaging pattern.'],['Chronic endometrial cancer as the acute cause','The abrupt midcycle adnexal event does not fit that presentation.']], 'Combine pregnancy exclusion, stable hemoglobin and collapsed cyst imaging.', 'clinical'),
q('Obstetrics','Pregnancy','Genitourinary menopause mucosal change','A postmenopausal patient has vaginal dryness, dyspareunia and burning. Examination shows pale thin friable mucosa without infectious organisms. Which process most directly explains these findings?', 'Reduced estrogen support of vaginal epithelium', 'Lower estrogen after menopause can thin the vaginal epithelium and reduce normal lubrication, causing dryness and painful intercourse. The lack of an infectious finding supports genitourinary syndrome of menopause rather than assuming all irritation is candidiasis.', [['Persistent high ovarian estrogen secretion','High estrogen would not explain the characteristic thin hypoestrogenic mucosa.'],['Mandatory Candida overgrowth','No fungal evidence is supplied and atrophic symptoms can be noninfectious.'],['Acute rupture of ovarian follicles','The postmenopausal mucosal pattern is not an ovulatory injury.']], 'Link noninfectious postmenopausal irritation to hypoestrogenic mucosal change.', 'clinical'),
q('Obstetrics','Pregnancy','Pelvic inflammatory disease infertility','A patient with previous untreated cervicitis develops bilateral pelvic pain, fever and cervical motion tenderness. Later, she has infertility despite ovulation and a normal uterine cavity. Which sequela most plausibly explains the infertility?', 'Tubal scarring after ascending infection', 'Ascending reproductive tract infection can damage the fallopian tubes and impair gamete or embryo transport. Preserved ovulation and a normal cavity make tubal injury especially relevant; pelvic inflammatory disease can also increase ectopic pregnancy risk.', [['Permanent cessation of every ovarian follicle','Tubal infection can impair fertility even when ovulation continues.'],['An isolated nonobstructive cervical ectropion','That does not explain postinfectious damage to reproductive transport pathways.'],['Mandatory congenital absence of the uterus','The normal uterine cavity excludes that congenital explanation.']], 'Connect an ascending pelvic infection to later tubal factor infertility.', 'clinical'),
q('Surgery','Respiratory','Flail chest paradoxical segment','After blunt thoracic trauma, a patient has several adjacent ribs fractured in two places each. A free chest-wall segment moves inward during inspiration while the surrounding chest expands. Which lesion explains the motion?', 'Flail chest', 'A rib segment disconnected from the surrounding bony cage follows intrathoracic pressure rather than normal chest expansion. Paradoxical motion identifies a flail segment; associated pulmonary contusion can contribute substantially to hypoxemia.', [['Isolated nondisplaced fracture of one rib','A single stable rib fracture does not create a free paradoxical segment.'],['Spontaneous diaphragmatic paralysis alone','That affects diaphragmatic excursion rather than a disconnected rib segment.'],['Chronic obstructive lung disease alone','Airway obstruction does not explain traumatic double rib fractures and focal motion.']], 'Connect double fractures of adjacent ribs to paradoxical chest-wall motion.'),
q('Surgery','Respiratory','Massive hemothorax examination','A patient becomes hypotensive after penetrating chest trauma. Breath sounds are absent on the injured side, percussion is dull and bedside ultrasound shows a large pleural fluid collection. Which cause best fits?', 'Hemothorax', 'Pleural blood can both compress the lung and produce hemorrhagic shock. Dullness and a fluid collection distinguish this pattern from a primarily air-filled pleural space; trauma makes blood the most concerning explanation for the acute collection.', [['Uncomplicated tension pneumothorax','Air typically causes hyperresonance rather than a large pleural fluid collection.'],['Isolated vocal-cord paralysis','That does not create unilateral pleural fluid or major blood loss.'],['Chronic stable pleural plaque','A stable pleural thickening cannot explain abrupt traumatic shock.']], 'Use pleural fluid and percussion to distinguish traumatic blood from pleural air.'),
q('Surgery','Cardiovascular','Traumatic tamponade obstructive pattern','After a stab wound near the sternum, a patient has hypotension, distended neck veins and a rapidly enlarging pericardial fluid collection on bedside ultrasound. The lungs have bilateral breath sounds. Which mechanism is causing shock?', 'Impaired cardiac filling from pericardial pressure', 'Blood confined within the pericardium can restrict diastolic filling and reduce cardiac output. The ultrasound finding plus venous congestion supports tamponade; blood loss may coexist, but elevated external cardiac pressure explains the obstructive component.', [['Primary loss of all circulating platelets','An isolated platelet disorder does not explain an expanding pericardial collection.'],['Diffuse left ventricular dilation from years of hypertension','The abrupt penetrating injury and fluid accumulation indicate an acute process.'],['Isolated tension pneumothorax on the absent-breath-sound side','Bilateral breath sounds and a pericardial collection favor cardiac compression.']], 'Distinguish traumatic pericardial obstruction from isolated volume-loss shock.'),
q('Surgery','Respiratory','Traumatic diaphragmatic rupture','After a high-speed collision, a patient has dyspnea and bowel sounds in the left chest. Imaging shows a nasogastric tube curling above the left hemidiaphragm within an air-filled structure. Which injury best fits?', 'Left diaphragmatic rupture with gastric herniation', 'A traumatic diaphragm defect allows abdominal viscera to enter the thorax. An intrathoracic stomach containing the nasogastric tube explains the abnormal air structure and bowel sounds, rather than assuming every posttraumatic chest lucency is pleural air.', [['Isolated simple rib fracture','A rib fracture does not relocate the stomach and nasogastric tube into the thorax.'],['Uncomplicated bronchial asthma','Asthma does not account for intrathoracic abdominal contents after trauma.'],['Tracheal obstruction by the nasogastric tube','The tube is described within an air-filled stomach rather than the airway.']], 'Identify herniated abdominal contents as evidence of traumatic diaphragm disruption.'),
q('Surgery','Gastrointestinal','Esophageal perforation after vomiting','A patient has violent retching followed by sudden severe chest pain and subcutaneous neck crepitus. CT shows mediastinal air and an esophageal contrast leak. Which lesion is present?', 'Transmural esophageal rupture', 'A full-thickness tear permits luminal contents and air to enter the mediastinum after a sudden pressure rise. The contrast leak distinguishes Boerhaave syndrome from a superficial mucosal laceration, which can bleed without mediastinal contamination.', [['Mallory-Weiss mucosal tear alone','A superficial tear does not explain a transmural contrast leak into the mediastinum.'],['Uncomplicated gastroesophageal reflux','Reflux alone does not cause acute mediastinal air and an esophageal wall leak.'],['Isolated spontaneous pneumothorax','That does not explain contrast escaping from the esophagus.']], 'Distinguish a full-thickness vomiting-associated rupture from a mucosal bleeding tear.'),
q('Surgery','Gastrointestinal','Mallory Weiss bleeding anatomy','After repeated retching, a patient vomits bright red blood. Endoscopy shows a linear tear confined to mucosa near the gastroesophageal junction without perforation. Which diagnosis fits?', 'Mallory-Weiss tear', 'Retching can shear mucosa at the gastroesophageal junction and cause upper gastrointestinal bleeding. The superficial endoscopic lesion differs from a transmural rupture, which allows mediastinal contamination and is not defined solely by hematemesis.', [['Boerhaave transmural rupture','The observed lesion is confined to mucosa and has no perforation.'],['Esophageal varices','Varices are dilated veins rather than a linear retching-associated mucosal tear.'],['Gastric outlet obstruction as the visible lesion','Obstruction does not itself describe the demonstrated superficial junctional tear.']], 'Identify mucosal rather than transmural injury after vomiting.'),
q('Surgery','Gastrointestinal','Gallstone ileus fistula pattern','An older patient has vomiting and small-bowel obstruction. CT shows pneumobilia and an ectopic calcified stone at the ileal transition point. No biliary instrumentation has occurred. Which route best explains the obstruction?', 'A biliary-enteric fistula allowed a gallstone into the bowel', 'Gallstone ileus is mechanical intestinal obstruction by a stone that entered through an abnormal biliary-enteric connection. Pneumobilia and an ectopic obstructing stone support this route; the term ileus does not mean diffuse paralytic bowel inactivity here.', [['Diffuse paralytic ileus without mechanical blockage','A stone at a discrete transition point establishes a mechanical cause.'],['Stone migration directly through the urinary bladder','A urinary pathway does not explain pneumobilia and an intraluminal intestinal stone.'],['A swallowed gallstone from an intact gallbladder','A gallbladder stone requires a connection to enter the intestinal lumen this way.']], 'Integrate pneumobilia with an ectopic obstructing stone to infer a biliary-enteric fistula.'),
q('Surgery','Gastrointestinal','Sigmoid volvulus torsion anatomy','An institutionalized older adult with chronic constipation develops marked abdominal distention and obstipation. CT shows a massively dilated sigmoid loop with a twisted mesenteric pedicle and distal decompression. Which process is present?', 'Sigmoid volvulus', 'Twisting of a redundant sigmoid and its mesentery creates a closed-loop obstruction and can impair vascular supply. The mesenteric whirl distinguishes a torsion mechanism from diffuse ileus, while the location distinguishes sigmoid from cecal volvulus.', [['Diffuse postoperative ileus','Diffuse motility failure does not create a focal twisted sigmoid pedicle.'],['Simple rectal hemorrhoids','Hemorrhoids do not cause a closed-loop sigmoid obstruction.'],['Primary gastric volvulus','The imaging localizes the twist to the sigmoid rather than the stomach.']], 'Recognize a focal mesenteric twist as a closed-loop colonic obstruction.'),
q('Surgery','Gastrointestinal','Cecal volvulus mobile right colon','A patient has acute obstruction. CT shows a markedly distended cecum displaced into the left upper abdomen with a twist involving its mesentery; the distal colon is decompressed. Which diagnosis fits?', 'Cecal volvulus', 'An abnormally mobile cecum can rotate around its mesentery and move away from its normal right-sided position. The displaced cecum and focal mesenteric twist distinguish this from sigmoid torsion or diffuse postoperative ileus.', [['Sigmoid volvulus','The twisted structure is identified as the cecum rather than the sigmoid.'],['Uncomplicated constipation without obstruction','Distal decompression and mesenteric twisting indicate mechanical obstruction.'],['Isolated gastritis','A gastric mucosal process does not explain the displaced obstructed cecum.']], 'Localize volvulus to the displaced cecum rather than inferring location from pain alone.'),
q('Surgery','Gastrointestinal','Duodenal hematoma after handlebar injury','A child develops epigastric pain and bilious vomiting one day after a bicycle handlebar strikes the abdomen. CT shows a thickened duodenal wall containing blood with luminal narrowing and no free air. Which lesion best explains obstruction?', 'Intramural duodenal hematoma', 'Blunt compression can cause blood to collect within the duodenal wall and narrow the lumen. Delayed vomiting with a wall hematoma and no free air supports obstructive mural injury rather than assuming an immediate full-thickness perforation.', [['Congenital pyloric stenosis presenting for the first time after trauma','That does not explain an acquired blood collection in the duodenal wall.'],['Uncomplicated splenic contusion as the direct obstruction','A splenic injury does not directly narrow the duodenal lumen.'],['Esophageal mucosal tear','That causes upper bleeding rather than a focal obstructing duodenal wall collection.']], 'Link delayed posttraumatic bilious obstruction to intramural duodenal bleeding.'),
q('Surgery','Renal','Pelvic fracture urethral injury','A patient with a pelvic fracture has blood at the urethral meatus and cannot void. He is otherwise stabilized. Before routine blind urethral catheter insertion, which investigation assesses the suspected injury?', 'Retrograde urethrography', 'Blood at the meatus after pelvic trauma raises concern for urethral disruption. Retrograde urethrography delineates the urethra before blind instrumentation, which can worsen an injury; routine urine dipstick testing cannot establish urethral continuity.', [['Blind repeated catheter attempts','Repeated blind passage may worsen a suspected urethral injury.'],['Routine urine dipstick alone','A urine chemistry test does not assess structural urethral continuity.'],['Upper gastrointestinal endoscopy','This does not image the urinary outflow tract after pelvic trauma.']], 'Prioritize anatomic urethral assessment before instrumentation after pelvic trauma.','clinical','prioritization'),
q('Surgery','Renal','Intraperitoneal bladder rupture','A patient sustains blunt lower abdominal trauma with a distended bladder. CT cystography shows contrast outlining bowel loops within the peritoneal cavity. Which injury pattern is demonstrated?', 'Intraperitoneal bladder rupture', 'Contrast surrounding intraperitoneal bowel loops indicates leakage through an intraperitoneal bladder wall defect, often at the dome. Extraperitoneal leakage instead tracks through perivesical tissues without freely outlining intestinal loops.', [['Isolated extraperitoneal bladder rupture','That produces perivesical extravasation rather than free contrast around bowel loops.'],['Ureteral stone without rupture','A stone does not explain cystographic contrast entering the peritoneal cavity.'],['Uncomplicated cystitis','Inflammation alone does not create the demonstrated structural leak.']], 'Use contrast distribution to distinguish intraperitoneal from extraperitoneal bladder injury.'),
q('Surgery','Nervous System','Epidural hematoma arterial anatomy','After a temporal skull fracture, a patient briefly loses consciousness, awakens and then deteriorates. CT shows a biconvex extra-axial hematoma limited by cranial sutures. Which vessel is classically injured?', 'Middle meningeal artery', 'A temporal fracture can tear the middle meningeal artery and create an expanding epidural collection. The lentiform suture-limited shape supports epidural blood; a lucid interval is suggestive but is neither required nor sufficient by itself.', [['Bridging cortical veins','Their injury more commonly causes a crescentic subdural collection.'],['Superior sagittal sinus in every case','This is not the classic artery associated with temporal epidural hemorrhage.'],['Posterior inferior cerebellar artery','That vessel does not occupy the temporal epidural compartment.']], 'Combine fracture location and extra-axial collection geometry to identify the bleeding source.'),
q('Surgery','Nervous System','Subdural hematoma bridging veins','An older patient taking anticoagulants develops progressive confusion after a minor fall. CT shows a crescentic collection crossing sutures but limited by dural reflections. Which vascular injury most often explains this?', 'Tearing of bridging veins', 'Bridging veins traverse the space between brain and dural venous sinuses and can tear with acceleration injury. Age-related brain volume loss increases vulnerability; the crescentic distribution supports subdural rather than suture-limited epidural hemorrhage.', [['Middle meningeal artery injury as the usual source','That classically produces an epidural rather than crescentic subdural collection.'],['Rupture of an extracranial scalp artery alone','A scalp vessel does not explain an intracranial extra-axial collection.'],['Isolated retinal artery occlusion','Retinal arterial disease does not produce subdural blood.']], 'Distinguish a venous subdural collection using age, injury and CT distribution.'),
q('Surgery','Nervous System','Basilar skull fracture CSF leak','Following head trauma, a patient has periorbital ecchymoses and clear unilateral nasal drainage. Laboratory testing identifies beta-2 transferrin in the fluid. Which conclusion is most appropriate?', 'A traumatic cerebrospinal fluid leak is present', 'Beta-2 transferrin strongly supports cerebrospinal fluid in nasal drainage. With skull-base trauma signs, this suggests a communication through a basilar fracture; appearance alone is less specific because ordinary nasal secretions can also be clear.', [['Clear color alone proves seasonal allergy','The trauma signs and cerebrospinal-fluid marker support a structural leak.'],['Normal nasal mucus always contains beta-2 transferrin','This marker is used because it is not ordinarily present in nasal secretions.'],['The finding establishes a spinal cord transection','A skull-base leak does not imply a transected spinal cord.']], 'Integrate a specific fluid marker with skull-base trauma signs.'),
q('Surgery','General Principles','Septal hematoma after nasal trauma','A patient has nasal obstruction after being struck in the face. Examination shows a tender fluctuant swelling on both sides of the nasal septum rather than a firm deviated septum. Which complication makes prompt drainage important?', 'Septal cartilage ischemia and necrosis', 'A septal hematoma separates cartilage from its nutrient-supplying perichondrium. Untreated pressure and infection can damage cartilage and cause deformity; fluctuation distinguishes the collection from a simple stable septal deviation.', [['Immediate malignant transformation of nasal bone','Cartilage ischemia, not acute malignant change, is the relevant risk.'],['Permanent obstruction of both optic nerves','That does not follow directly from a localized septal collection.'],['Normal spontaneous protection of cartilage nutrition','Separation from perichondrium impairs rather than protects cartilage nutrition.']], 'Explain why a posttraumatic septal collection threatens avascular cartilage.'),
q('Surgery','Musculoskeletal','Posterior hip dislocation sciatic risk','After a dashboard injury, a patient holds the hip flexed, adducted and internally rotated. Imaging confirms posterior hip dislocation. Weak ankle dorsiflexion appears. Which nerve is most concerning?', 'Sciatic nerve', 'Posterior displacement of the femoral head can injure the sciatic nerve, particularly fibers serving the common fibular division. Dorsiflexion weakness fits this risk; the posture and imaging localize the injury to a posterior hip dislocation.', [['Femoral nerve','Femoral injury primarily weakens knee extension rather than ankle dorsiflexion.'],['Obturator nerve','That primarily supplies hip adductors rather than ankle dorsiflexors.'],['Superior gluteal nerve alone','That affects hip abduction rather than the distal dorsiflexion deficit.']], 'Connect posterior hip displacement and a distal motor deficit to sciatic injury.'),
q('Surgery','Musculoskeletal','Supracondylar fracture vascular concern','A child falls on an extended arm and sustains a displaced supracondylar humeral fracture. The hand is cool with delayed capillary refill and a weak radial pulse. Which injured structure requires urgent assessment?', 'Brachial artery', 'A displaced supracondylar fragment can compromise the brachial artery near the elbow. A cool poorly perfused hand indicates vascular threat rather than an isolated sensory neuropraxia, and persistent ischemia can damage forearm muscles.', [['Axillary vein as the sole explanation','The injury location and distal arterial underperfusion favor brachial arterial compromise.'],['Radial collateral ligament alone','A ligament injury does not explain a cool poorly perfused hand.'],['Median nerve only with normal arterial flow assumed','A motor or sensory injury alone cannot account for the described perfusion deficit.']], 'Prioritize the vascular implication of a displaced pediatric elbow fracture.'),
q('Surgery','Musculoskeletal','Monteggia injury paired lesion','A patient has a proximal ulnar shaft fracture after a fall. Forearm radiographs also show the radial head no longer aligned with the capitellum. Which injury pattern is present?', 'Monteggia fracture-dislocation', 'A proximal ulnar fracture with radial head dislocation defines a Monteggia injury. Checking the adjacent joint prevents missing the dislocation; Galeazzi instead combines a distal radial shaft fracture with distal radioulnar disruption.', [['Galeazzi fracture-dislocation','That involves a radial shaft fracture and distal radioulnar joint disruption.'],['Isolated scaphoid fracture','A carpal fracture does not explain the proximal ulna and radial head findings.'],['Simple lateral epicondylitis','A tendinopathy does not produce this fracture-dislocation pattern.']], 'Identify the joint injury accompanying a proximal ulnar fracture.'),
q('Surgery','Musculoskeletal','Galeazzi injury distal radioulnar joint','A patient has a distal third radial shaft fracture with widening and instability of the distal radioulnar joint. The radial head remains aligned with the capitellum. Which injury pattern fits?', 'Galeazzi fracture-dislocation', 'A radial shaft fracture paired with distal radioulnar joint injury defines Galeazzi fracture-dislocation. The preserved proximal radial head alignment distinguishes this from Monteggia injury and emphasizes examining both ends of the injured forearm.', [['Monteggia fracture-dislocation','That pairs ulnar fracture with proximal radial head dislocation.'],['Isolated nursemaid elbow','A radial head subluxation in a small child does not explain a radial shaft fracture.'],['Anterior shoulder dislocation','The shoulder is anatomically separate from the documented forearm joint injury.']], 'Recognize distal radioulnar disruption accompanying a radial shaft fracture.'),
q('Surgery','Musculoskeletal','Open fracture infection pathway','A patient has a tibial fracture with a nearby skin wound communicating with the fracture hematoma. The bone is not visible externally. Which classification best describes the injury?', 'Open fracture', 'Communication between the external environment and the fracture defines an open fracture even without visible protruding bone. The tract creates contamination risk; wound size or the absence of exposed bone does not convert the injury into a closed fracture.', [['Closed fracture because bone is not exposed','External visibility of bone is not required when a communicating wound exists.'],['Simple abrasion unrelated to fracture by definition','A demonstrated tract to the hematoma establishes communication.'],['Pathologic fracture solely because skin is broken','Pathologic fracture refers to weakened bone, not simply an overlying wound.']], 'Define an open fracture by communication rather than visible protruding bone.','clinical','application'),
q('Surgery','Renal','Testicular torsion clinical pattern','A 15-year-old develops abrupt severe unilateral scrotal pain and vomiting. The affected testis lies high and horizontally, and the ipsilateral cremasteric reflex is absent. There are no urinary symptoms. Which diagnosis is most concerning?', 'Testicular torsion', 'Sudden pain with an abnormal testicular lie and absent cremasteric reflex strongly suggests spermatic cord twisting and threatened blood supply. Urinary symptoms are not required; delay risks ischemic loss, unlike assuming all painful scrotal conditions are infection.', [['Uncomplicated epididymitis as the only possibility','The abrupt onset and high transverse testis favor a vascular torsion pattern.'],['Painless hydrocele','A simple fluid collection does not explain this acute ischemic pattern.'],['Stable varicocele','A chronic venous dilation usually does not cause abrupt severe pain with an abnormal lie.']], 'Integrate onset, testicular position and reflex findings in an acute scrotum.'),
q('Surgery','Renal','Hydrocele transillumination','A patient has gradual painless scrotal enlargement. The swelling transilluminates, and ultrasound shows fluid surrounding a normal testis without an intratesticular mass. Which diagnosis best fits?', 'Hydrocele', 'Fluid within the tunica vaginalis surrounding an otherwise normal testis explains the painless transilluminating swelling. Ultrasound helps exclude a hidden intratesticular lesion; transillumination alone is useful but does not replace examination of the testis.', [['Solid intratesticular tumor as shown on this ultrasound','The imaging instead demonstrates extra-testicular fluid and a normal testis.'],['Acute spermatic cord torsion','That typically produces abrupt pain and perfusion concern rather than this chronic fluid pattern.'],['Incarcerated bowel hernia','A herniated bowel loop is not described as simple fluid surrounding the testis.']], 'Use sonographic location and fluid character to identify a hydrocele.'),
q('Surgery','Renal','Varicocele positional venous dilation','A young adult has a dull left scrotal ache and a soft collection of tortuous vessels above the testis. The swelling enlarges standing or with Valsalva and decreases supine. Which structure is dilated?', 'Pampiniform venous plexus', 'A varicocele is dilation of the pampiniform plexus, often more evident when standing or straining. The positional venous pattern differs from a solid testicular mass or simple hydrocele, and testicular size and fertility symptoms may guide further assessment.', [['Tunica vaginalis filled with arterial blood in every case','A varicocele is venous dilation rather than obligatory hemorrhage into a fluid sac.'],['Seminiferous tubules protruding through the skin','The palpable structures are dilated veins, not exposed testicular tubules.'],['Ureter within the scrotum','The ureter does not normally form this positional scrotal venous collection.']], 'Identify a positional pampiniform venous lesion rather than a solid scrotal mass.'),
q('Surgery','Dermatology','Necrotizing soft tissue infection warning','A patient has rapidly worsening leg pain after a minor wound. Pain extends beyond visible erythema, fever and hypotension develop, and the skin becomes dusky with bullae. Which diagnosis demands urgent surgical consideration?', 'Necrotizing soft-tissue infection', 'Disproportionate spreading pain, systemic toxicity and evolving skin injury suggest deep fascial infection rather than uncomplicated cellulitis. Surface appearance can underestimate tissue involvement; absence of early crepitus would not safely exclude the process.', [['Uncomplicated superficial dermatitis','Rapid severe pain and shock are inconsistent with a benign superficial rash.'],['Stable venous stasis pigmentation','Chronic stasis changes do not explain acute systemic toxicity and bullae.'],['Isolated painless lipoma','A benign fatty mass does not cause the described rapidly progressive illness.']], 'Identify deep destructive infection from disproportionate pain and systemic deterioration.'),
q('Surgery','Renal','Fournier perineal infection','A patient with diabetes has severe perineal pain, fever, swollen dusky scrotal skin and crepitus extending into the perineum. The testes themselves appear perfused on ultrasound. Which diagnosis best fits?', 'Fournier gangrene', 'Necrotizing infection of perineal fascial tissues can involve the scrotal wall while sparing testicular perfusion because the testes have a separate arterial supply. Severe systemic illness and fascial gas distinguish this from a simple isolated testicular infection.', [['Isolated uncomplicated hydrocele','A sterile fluid collection does not explain tissue gas and severe systemic toxicity.'],['Testicular torsion as the cause of fascial gas','Torsion threatens testicular blood flow but does not explain spreading perineal crepitus.'],['Normal diabetic skin change','Diabetes increases risk but does not make destructive perineal findings physiologic.']], 'Recognize perineal fascial infection despite preserved testicular perfusion.'),
q('Surgery','General Principles','Breast fibroadenoma clinical pattern','A 22-year-old finds a firm rubbery mobile breast mass with smooth margins. Ultrasound shows an oval well-circumscribed solid lesion oriented parallel to the skin. Which diagnosis is most consistent?', 'Fibroadenoma', 'A mobile, circumscribed oval solid mass in a young adult is typical of fibroadenoma. These features suggest benignity but are not a substitute for appropriate imaging assessment or tissue evaluation when findings are atypical, growing or discordant.', [['Inflammatory breast cancer','That usually presents with diffuse inflammatory skin change rather than this mobile circumscribed lesion.'],['Breast abscess','An abscess more often has pain, inflammatory findings and a fluid-containing collection.'],['Diffuse duct ectasia','That more often involves dilated subareolar ducts and nipple discharge.']], 'Integrate age, mobility and ultrasound orientation in a benign breast mass pattern.'),
q('Surgery','General Principles','Inflammatory breast cancer lymphatics','A nonlactating patient develops rapid diffuse breast enlargement, erythema and peau d orange without fever. Antibiotics have not helped. Biopsy identifies carcinoma involving dermal lymphatics. What causes the skin texture?', 'Obstruction of cutaneous lymphatic drainage', 'Tumor involvement of dermal lymphatics impairs drainage and produces skin edema around tethered follicles, causing peau d orange. Persistent diffuse inflammatory change without an infectious response warrants cancer assessment even without a discrete palpable mass.', [['Increased sweat gland drainage','Enhanced drainage does not explain edema from lymphatic tumor involvement.'],['Uncomplicated lactational milk stasis','The patient is not lactating and biopsy demonstrates dermal lymphatic carcinoma.'],['Complete arterial occlusion of the breast','The demonstrated lesion affects lymphatic drainage rather than proving arterial infarction.']], 'Explain malignant peau d orange through dermal lymphatic obstruction.'),
q('Surgery','General Principles','Phyllodes stromal breast tumor','A 45-year-old has a rapidly enlarging painless breast mass. Core tissue shows a fibroepithelial lesion with hypercellular stroma forming leaflike projections. Which tumor is most consistent?', 'Phyllodes tumor', 'Leaflike architecture and increased stromal cellularity support phyllodes tumor, particularly with rapid growth. It is a fibroepithelial tumor with variable biologic behavior; rapid growth alone does not establish the malignant grade.', [['Simple intraductal papilloma','That is a ductal papillary lesion rather than the described leaflike stromal tumor.'],['Inflammatory carcinoma proven by growth rate alone','The tissue architecture supports phyllodes and growth alone does not assign carcinoma.'],['Uncomplicated breast cyst','A cyst does not show a hypercellular solid fibroepithelial stroma.']], 'Identify a leaflike stromal breast lesion while avoiding grade inference from growth alone.'),
q('Surgery','General Principles','Intraductal papilloma discharge','A patient has spontaneous bloody discharge from one nipple duct and a small subareolar lesion. Tissue sampling shows benign papillary fronds with fibrovascular cores and an intact myoepithelial layer. Which diagnosis fits?', 'Intraductal papilloma', 'A benign papillary proliferation within a duct can cause unilateral bloody discharge. Fibrovascular cores and retained myoepithelial cells support papilloma; the symptom alone still requires evaluation because malignant lesions can also cause discharge.', [['Physiologic bilateral milk secretion','Spontaneous single-duct bloody discharge is not the usual physiologic pattern.'],['Fibroadenoma as the demonstrated ductal lesion','Fibroadenoma is not defined by papillary fronds inside a duct.'],['Invasive carcinoma established by discharge alone','The supplied histology is benign and the symptom alone cannot establish invasion.']], 'Integrate single-duct bleeding with benign papillary ductal histology.'),
];
